import{_ as l,a0 as r,w as i,s as C,ao as u,I as s,x as o,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Linus Torvalds坦言所有CLA都不够完美，Canonical有话说 | LCTT x X-CMD","titleTemplate":false,"description":"Linus Torvalds坦言所有CLA都不够完美，Canonical有话说 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linus Torvalds坦言所有CLA都不够完美，Canonical有话说 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linus Torvalds坦言所有CLA都不够完美，Canonical有话说 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linus Torvalds Says All Contributor License Agreements Are Broken","title":"Linus Torvalds坦言所有CLA都不够完美，Canonical有话说","tag":"201401","desc":""},"relativePath":"201401/Linus Torvalds Says All Contributor License Agreements Are Broken.md","filePath":"[post].md"}'),p={name:"201401/Linus Torvalds Says All Contributor License Agreements Are Broken.md"};function L(A,n,d,T,m,c){const t=r("Link");return i(),C("div",null,[n[11]||(n[11]=u('<h1 id="linus-torvalds坦言所有cla都不够完美-canonical有话说" tabindex="-1">Linus Torvalds坦言所有CLA都不够完美，Canonical有话说 <a class="header-anchor" href="#linus-torvalds坦言所有cla都不够完美-canonical有话说" aria-label="Permalink to “Linus Torvalds坦言所有CLA都不够完美，Canonical有话说”">​</a></h1><p><strong>一场关于 Canonical 公司的贡献者许可协议的争论已经持续了好几天，现在连 Linus Torvalds 也加入这场论战了，呃，这次他比较心平气和了一点。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Linus-Torvalds-Says-All-Contributor-License-Agreements-Are-Broken-418978-2.jpg" alt=""></p><p>贡献者许可协议（CLA）允许你的软件贡献者（比如 Canonical，Apache 以及其他贡献者）在这个应用需要保护的方面提供法律保护，比如版权。</p><p>到了 Canonical 宣布使用 CLA，事情就变得有点耐人寻味了。Canonical 是一家商业公司，为了生存下去，它得赚钱，并且它的目标绝不仅仅是发行 Ubuntu 操作系统，它需要盈利。于是乎，Canonical 公司利用 CLA 将一些软件通过私有许可发行出来。（2011年7月份，Canonical 开始让贡献者签署一份 CLA 文件，文件表示贡献者可以保留自己的版权，同时要授权 Canonical 公司可以改变贡献者的许可协议 —— 译者注。）</p><blockquote><p>“公平地说，人们只是讨厌 Canonical。那些 FSF 和 Apache 基金会的 CLA 也是这副德行。他们只是没有因为修改许可协议而受到非议，但是这些版权转换工作最终将会消灭整个社区。”</p></blockquote><blockquote><p>“基本上，在 CLA 下你不可能获得像 Linux 内核一样那么多的随机驱动补丁。因此不管多少人想试水 CLA，不管改不改这个协议，都一样，所有 CLA 都有本质上的缺陷，”Linus Torvals 在 Google+ 上面发帖说道。</p></blockquote><p>Ubuntu 社区经理 Jono Bacon 解释为什么 Canonical 的 CLA 会走这条道，以及它不能给那些想为项目作贡献的人设置障碍的原因。</p><blockquote><p>“这些都是社区贡献的问题。社区一直存在很多问题：开发语言的选择、VCS、管理方式、社区讨论的口音、如何决定方案、如何回顾分支、bug 管理、CI 工作流程以及其他无数问题。CLA 仅仅是其中一个。有人欢喜，有人讨厌，萝卜青菜各有所爱罢了。”</p></blockquote><blockquote><p>“我不认为 Canonical 在 CLA 方面表现得不够诚意，也不关心为什么它会认为它的 CLA 方案很有必要。Canonical 在人们印象中是完美无瑕的吗？不见得。那它危险吗？它虚伪吗？当然不。”Jono Bacon 说道。</p></blockquote><hr>',11)),s("p",null,[n[1]||(n[1]=o("via: ",-1)),e(t,{href:"http://news.softpedia.com/news/Linus-Torvalds-Says-All-Contributor-License-Agreements-Are-Broken-418978.shtml"},{default:a(()=>[...n[0]||(n[0]=[o("http://news.softpedia.com/news/Linus-Torvalds-Says-All-Contributor-License-Agreements-Are-Broken-418978.shtml",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=o("译者：",-1)),e(t,{href:"https://github.com/bazz2"},{default:a(()=>[...n[2]||(n[2]=[o("bazz2",-1)])]),_:1}),n[5]||(n[5]=o(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...n[3]||(n[3]=[o("wxy",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=o("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...n[6]||(n[6]=[o("LCTT",-1)])]),_:1}),n[9]||(n[9]=o(" 原创翻译，",-1)),e(t,{href:"http://linux.cn/"},{default:a(()=>[...n[7]||(n[7]=[o("Linux中国",-1)])]),_:1}),n[10]||(n[10]=o(" 荣誉推出",-1))])])}const v=l(p,[["render",L]]);export{g as __pageData,v as default};
